import fitz, numpy as np
d = fitz.open('eprint/2020solar.pdf')
p = d[0]
segs = []
for dr in p.get_drawings():
    if dr['color'] == (1.0,0.0,0.0) and dr.get('dashes') == '[] 0' and dr['type']=='s':
        pts=[]
        for it in dr['items']:
            if it[0]=='l':
                pts.append((it[1].x, it[1].y)); pts.append((it[2].x, it[2].y))
            elif it[0]=='c':
                pts.extend([(pt.x,pt.y) for pt in it[1:5]])
        xs=[q[0] for q in pts]; ys=[q[1] for q in pts]
        segs.append((min(xs),max(xs),min(ys),max(ys),len(pts),pts))
for s in segs:
    print([round(v,1) for v in s[:4]], s[4])
